export function isPointer(value) {
    return value.kind === "pointer";
}
export function diffHeap(step1, step2) {
    const destroyed = Object.keys(step1.heap).filter(x => step2.heap[x] === undefined);
    const created = Object.keys(step2.heap).filter(x => step1.heap[x] === undefined);
    const updated = Object.keys(step2.heap)
        .filter(x => step1.heap[x] !== undefined)
        .filter(x => JSON.stringify(step1.heap[x]) !== JSON.stringify(step2.heap[x]));
    return { destroyed, created, updated };
}
export function diffStack(step1, step2) {
    const step1IDs = step1.stack_frames.map(x => x.frame_id);
    const step2IDs = step2.stack_frames.map(x => x.frame_id);
    const id2frame = (step, id) => step.stack_frames.find(({ frame_id }) => frame_id === id);
    const destroyed = step1IDs.filter(x => !step2IDs.includes(x));
    const created = step2IDs.filter(x => !step1IDs.includes(x));
    const updated = step2IDs.filter(frameId => !created.includes(frameId) &&
        JSON.stringify(id2frame(step1, frameId)) !==
            JSON.stringify(id2frame(step2, frameId)));
    return { destroyed, created, updated };
}
